#!/usr/bin/env node
import { readFile } from "node:fs/promises";
import process from "node:process";

const [command, ...args] = process.argv.slice(2);
const baseUrl = (process.env.PROVENANCE_API_URL || "http://localhost:3000").replace(/\/$/u, "");
const apiKey = process.env.PROVENANCE_API_KEY?.trim();
const TRANSFORM_MODES = new Set(["parity", "natural", "clarity", "concise", "formal"]);
const TRANSFORM_PURPOSES = new Set(["general", "email", "work", "academic", "social"]);
const TRANSFORM_INTENSITIES = new Set(["light", "balanced", "strong"]);

function usage(exitCode = 0) {
  console.error(`Usage:
  PROVENANCE_API_KEY=pc_sk_... npm run provenance:cli -- usage
  PROVENANCE_API_KEY=pc_sk_... npm run provenance:cli -- scan <file|-> [none|conservative|aggressive]
  PROVENANCE_API_KEY=pc_sk_... npm run provenance:cli -- transform <file|-> <parity|natural|clarity|concise|formal> [general|email|work|academic|social] [light|balanced|strong] [operation-id]

Optional: PROVENANCE_API_URL=https://your-host.example`);
  process.exit(exitCode);
}

if (!command || !["usage", "scan", "transform"].includes(command)) usage(1);
if (!apiKey) {
  console.error("PROVENANCE_API_KEY is required.");
  process.exit(1);
}

async function readInput(path) {
  if (!path) usage(1);
  if (path === "-") {
    const chunks = [];
    for await (const chunk of process.stdin) chunks.push(chunk);
    return Buffer.concat(chunks).toString("utf8");
  }
  return readFile(path, "utf8");
}

async function request(path, init = {}) {
  const response = await fetch(`${baseUrl}${path}`, {
    ...init,
    headers: {
      authorization: `Bearer ${apiKey}`,
      ...(init.body ? { "content-type": "application/json" } : {}),
      ...(init.headers || {}),
    },
  });
  const body = await response.json().catch(() => ({ error: { message: "Non-JSON response" } }));
  if (!response.ok) {
    console.error(JSON.stringify(body, null, 2));
    process.exit(1);
  }
  console.log(JSON.stringify(body, null, 2));
}

if (command === "usage") {
  await request("/api/v1/usage");
} else if (command === "scan") {
  const text = await readInput(args[0]);
  const sanitize = args[1] || "none";
  if (!["none", "conservative", "aggressive"].includes(sanitize)) usage(1);
  await request("/api/v1/scan", { method: "POST", body: JSON.stringify({ text, sanitize }) });
} else {
  const text = await readInput(args[0]);
  const mode = args[1];
  if (!mode || !TRANSFORM_MODES.has(mode)) usage(1);
  let cursor = 2;
  let purpose = "general";
  let intensity = "balanced";
  if (TRANSFORM_PURPOSES.has(args[cursor])) purpose = args[cursor++];
  if (TRANSFORM_INTENSITIES.has(args[cursor])) intensity = args[cursor++];
  const operationId = args[cursor] || crypto.randomUUID();
  await request("/api/v1/transform", { method: "POST", body: JSON.stringify({ operationId, text, mode, purpose, intensity }) });
}

"use client";

import Script from "next/script";
import { useCallback, useEffect, useRef, useState } from "react";
import { getTurnstileSiteKey } from "@/lib/public-config";

type TurnstileApi = {
  render: (element: HTMLElement, options: { sitekey: string; action: string; callback: (token: string) => void; "expired-callback": () => void; "error-callback": () => void; }) => string;
  remove: (id: string) => void;
};

function api() { return (window as unknown as { turnstile?: TurnstileApi }).turnstile; }

export function TurnstileWidget({ action, onToken, resetKey = 0 }: { action: string; onToken: (token: string | null) => void; resetKey?: number; }) {
  const sitekey = getTurnstileSiteKey();
  const testBypass = process.env.NODE_ENV !== "production" && process.env.NEXT_PUBLIC_TURNSTILE_TEST_BYPASS === "1";
  const elementRef = useRef<HTMLDivElement | null>(null);
  const widgetRef = useRef<string | null>(null);
  const [ready, setReady] = useState(false);

  const renderWidget = useCallback(() => {
    if (testBypass) { onToken("dev-bypass"); return; }
    if (!sitekey || !elementRef.current || !api()) return;
    if (widgetRef.current) api()?.remove(widgetRef.current);
    onToken(null);
    widgetRef.current = api()!.render(elementRef.current, {
      sitekey,
      action,
      callback: token => onToken(token),
      "expired-callback": () => onToken(null),
      "error-callback": () => onToken(null),
    });
  }, [action, onToken, sitekey, testBypass]);

  useEffect(() => { if (ready || testBypass) renderWidget(); return () => { if (widgetRef.current) api()?.remove(widgetRef.current); widgetRef.current = null; }; }, [ready, resetKey, renderWidget, testBypass]);

  if (testBypass) return <span className="privacy-note" data-testid="turnstile-bypass">Challenge bypass enabled for local tests.</span>;
  if (!sitekey) return <span className="privacy-note">Bot challenge is not configured.</span>;
  return <><Script src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit" strategy="afterInteractive" onReady={() => setReady(true)} /><div ref={elementRef} data-testid={`turnstile-${action}`} /></>;
}

import { isDevelopmentTurnstileBypass } from "@/lib/server/env";

const VERIFY_URL = "https://challenges.cloudflare.com/turnstile/v0/siteverify";
const PREVIEW_TEST_SECRET = "1x0000000000000000000000000000000AA";

interface TurnstileResponse { success?: boolean; action?: string; hostname?: string; "error-codes"?: string[]; }
export interface ChallengeResult { ok: boolean; reason?: "missing_token" | "not_configured" | "verification_failed" | "action_mismatch"; bypassed?: boolean; }

function effectiveSecret() {
  const configured = process.env.TURNSTILE_SECRET_KEY?.trim();
  if (configured) return configured;
  return process.env.VERCEL_ENV === "preview" ? PREVIEW_TEST_SECRET : undefined;
}

export async function verifyTurnstile(token: string | undefined, expectedAction: string, fetcher: typeof fetch = fetch): Promise<ChallengeResult> {
  if (isDevelopmentTurnstileBypass() && token === "dev-bypass") return { ok: true, bypassed: true };
  const secret = effectiveSecret();
  if (!secret) return { ok: false, reason: "not_configured" };
  if (!token || token.length > 2048) return { ok: false, reason: "missing_token" };
  try {
    const response = await fetcher(VERIFY_URL, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ secret, response: token }) });
    if (!response.ok) return { ok: false, reason: "verification_failed" };
    const result = await response.json() as TurnstileResponse;
    if (!result.success) return { ok: false, reason: "verification_failed" };
    if (result.action && result.action !== expectedAction) return { ok: false, reason: "action_mismatch" };
    return { ok: true };
  } catch { return { ok: false, reason: "verification_failed" }; }
}

import { getCreditBalance } from "@/lib/billing/server";
import { authenticateDeveloperRequest } from "@/lib/developer-api";
import { apiError, apiOk, requestContext, retryAfter } from "@/lib/server/api";
import { requestSubjectKey } from "@/lib/server/observability";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";

export async function GET(request: Request) {
  const context = requestContext(request, "/api/v1/usage");
  let identity;
  try { identity = await authenticateDeveloperRequest(request); }
  catch { return apiError(context, "developer_api_unavailable", "Developer API authentication is unavailable.", 503); }
  if (!identity) return apiError(context, "invalid_api_key", "A valid Bearer API key is required.", 401, { "www-authenticate": "Bearer" });

  const subject = requestSubjectKey(request, identity.keyId);
  const limit = consumeRateLimit("developer-usage", subject, configuredLimit("RATE_LIMIT_DEVELOPER_USAGE_PER_MINUTE", 30), 60_000);
  if (!limit.allowed) return apiError(context, "rate_limited", "Developer usage rate limit exceeded.", 429, retryAfter(limit.retryAfterSeconds));

  try {
    const balance = await getCreditBalance(identity.userId);
    return apiOk(context, { balance, key: { prefix: identity.prefix } }, 200, { "cache-control": "no-store" });
  } catch {
    return apiError(context, "billing_unavailable", "Usage balance is temporarily unavailable.", 503);
  }
}

